DROP TABLE IF EXISTS `member_packages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `member_packages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL,
  `package_id` int(11) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `sessions_total` int(11) DEFAULT NULL,
  `sessions_remaining` int(11) DEFAULT NULL,
  `pt_id` int(11) DEFAULT NULL,
  `pt_session_unit_price` decimal(12,2) DEFAULT NULL,
  `price_paid` decimal(12,2) NOT NULL DEFAULT 0.00,
  `status` enum('pending','active','expired','cancelled') NOT NULL DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_member_packages_member_status` (`member_id`,`status`,`end_date`),
  KEY `idx_member_packages_pt_status` (`pt_id`,`status`,`end_date`),
  KEY `idx_member_packages_package` (`package_id`),
  KEY `fk_member_packages_creator` (`created_by`),
  CONSTRAINT `fk_member_packages_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_member_packages_member` FOREIGN KEY (`member_id`) REFERENCES `members` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_member_packages_package` FOREIGN KEY (`package_id`) REFERENCES `packages` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_member_packages_pt` FOREIGN KEY (`pt_id`) REFERENCES `trainers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=128 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

