--
-- Table structure for table `membership_requests`
--

DROP TABLE IF EXISTS `membership_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `membership_requests` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL,
  `request_type` enum('new_package','renew','upgrade','cancel','change_trainer') NOT NULL,
  `requested_package_id` int(11) DEFAULT NULL,
  `requested_trainer_id` int(11) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `status` enum('pending','approved','rejected','cancelled') NOT NULL DEFAULT 'pending',
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_membership_requests_member` (`member_id`,`status`,`created_at`),
  KEY `fk_membership_requests_package` (`requested_package_id`),
  KEY `fk_membership_requests_trainer` (`requested_trainer_id`),
  KEY `fk_membership_requests_reviewer` (`reviewed_by`),
  CONSTRAINT `fk_membership_requests_member` FOREIGN KEY (`member_id`) REFERENCES `members` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_membership_requests_package` FOREIGN KEY (`requested_package_id`) REFERENCES `packages` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_membership_requests_reviewer` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_membership_requests_trainer` FOREIGN KEY (`requested_trainer_id`) REFERENCES `trainers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

