--

DROP TABLE IF EXISTS `pt_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pt_sessions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `trainer_id` int(11) NOT NULL,
  `member_id` int(11) NOT NULL,
  `member_package_id` int(11) DEFAULT NULL,
  `schedule_id` bigint(20) DEFAULT NULL,
  `session_date` datetime NOT NULL,
  `confirmed_by` int(11) DEFAULT NULL,
  `status` enum('pending','confirmed','cancelled','no_show') NOT NULL DEFAULT 'confirmed',
  `commission_rate` decimal(5,2) NOT NULL DEFAULT 0.50,
  `commission_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `note` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_pt_sessions_trainer_date` (`trainer_id`,`session_date`,`status`),
  KEY `idx_pt_sessions_member_date` (`member_id`,`session_date`,`status`),
  KEY `fk_pt_sessions_member_package` (`member_package_id`),
  KEY `fk_pt_sessions_schedule` (`schedule_id`),
  KEY `fk_pt_sessions_confirmed_by` (`confirmed_by`),
  CONSTRAINT `fk_pt_sessions_confirmed_by` FOREIGN KEY (`confirmed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pt_sessions_member` FOREIGN KEY (`member_id`) REFERENCES `members` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_pt_sessions_member_package` FOREIGN KEY (`member_package_id`) REFERENCES `member_packages` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pt_sessions_schedule` FOREIGN KEY (`schedule_id`) REFERENCES `training_schedules` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pt_sessions_trainer` FOREIGN KEY (`trainer_id`) REFERENCES `trainers` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=219 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `pt_sessions`
--

LOCK TABLES `pt_sessions` WRITE;
/*!40000 ALTER TABLE `pt_sessions` DISABLE KEYS */;
